# test: enclosed zeros via diagonal-blocking flood fill from border
import sys
from collections import deque
H,W=15,5
def enclosed(g):
    blocked=lambda r,c: g[r][c]==5
    seen=set()
    q=deque()
    # seed: border zeros that can "escape" (not enclosed)
    for r in range(H):
        for c in (0,W-1):
            if not blocked(r,c): q.append((r,c)); seen.add((r,c))
    for c in range(W):
        for r in (0,H-1):
            if not blocked(r,c) and (r,c) not in seen: q.append((r,c)); seen.add((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen:
                if blocked(nr,nc):
                    # diagonal escape: move diagonally around corner if both orth neighbors free
                    continue
                seen.add((nr,nc)); q.append((nr,nc))
    return {(r,c) for r in range(H) for c in range(W) if g[r][c]==0 and (r,c) not in seen}
